var registry = struct {
    sync.RWMutex
    m map[string]func() Repository
}{m: map[string]func() Repository{}}

// Register panics on a duplicate name, as sql.Register does.
func Register(name string, f func() Repository) {
    registry.Lock()
    defer registry.Unlock()
    if _, dup := registry.m[name]; dup {
        panic("duplicate service: " + name)
    }
    registry.m[name] = f
}

